import pandas as pd
import re, json

logs = pd.read_csv('/app/data/test_center_logs.csv')

codebook_files = {
    'P1_POWER': '/app/data/codebook_P1_POWER.csv',
    'P2_CTRL': '/app/data/codebook_P2_CTRL.csv',
    'P3_RF': '/app/data/codebook_P3_RF.csv',
}

codebooks = {}

def classify_keywords(keywords):
    entries = []
    for kw in keywords:
        kw_strip = kw.strip()
        if not kw_strip:
            continue
        kw_low = kw_strip.lower()
        # identify specific tokens
        is_specific = False
        if re.search(r'\d', kw_strip):
            is_specific = True
        elif '_' in kw_strip:
            is_specific = True
        elif re.fullmatch(r'[A-Z]{2,}[A-Z0-9_]*', kw_strip):
            if kw_low not in {'esd', 'icc', 'ok', 'ng'}:
                is_specific = True
        entries.append((kw_strip, kw_low, is_specific))
    return entries

for pid, path in codebook_files.items():
    cb = pd.read_csv(path)
    entries = []
    for _, row in cb.iterrows():
        keywords = [k.strip() for k in str(row['keywords_examples']).split(',')]
        kw_entries = classify_keywords(keywords)
        station_scope = set(str(row['station_scope']).split(';')) if pd.notna(row['station_scope']) else set()
        entries.append({
            'code': row['code'],
            'label': row['standard_label'],
            'keywords': kw_entries,
            'station_scope': station_scope,
        })
    codebooks[pid] = entries

# synonym expansions for matching
syn_patterns = [
    (re.compile(r'(桥连|连锡|锡桥)'), ' bridge'),
    (re.compile(r'(少锡|假焊)'), ' cold solder'),
    (re.compile(r'(断路)'), ' open'),
    (re.compile(r'\bOS\b', re.IGNORECASE), ' open short'),
]

split_regex = re.compile(r'(;|；|\n|\r|\t|\|)')

def split_segments(text):
    if text is None or (isinstance(text, float) and pd.isna(text)):
        return []
    s = str(text)
    parts = []
    last = 0
    for m in split_regex.finditer(s):
        end = m.start()
        seg = s[last:end].strip()
        if seg:
            parts.append(seg)
        last = m.end()
    tail = s[last:].strip()
    if tail:
        parts.append(tail)
    final_parts = []
    for seg in parts:
        subparts = re.split(r'\s+[+&]\s+', seg)
        for sp in subparts:
            sp = sp.strip()
            if sp:
                final_parts.append(sp)
    return final_parts


def expand_text(text):
    expanded = text
    for pat, add in syn_patterns:
        if pat.search(expanded):
            expanded += add
    return expanded


def match_segment(product_id, station, segment):
    seg_text = segment
    expanded = expand_text(seg_text)
    seg_low = expanded.lower()

    best = None
    best_score = 0.0
    best_matches = []

    for entry in codebooks.get(product_id, []):
        matched_specific = 0
        matched_generic = 0
        total_specific = 0
        total_generic = 0
        matched_keywords = []

        for kw_strip, kw_low, is_specific in entry['keywords']:
            if is_specific:
                total_specific += 1
            else:
                total_generic += 1

            matched = False
            if re.search(r'[A-Za-z]', kw_strip):
                if kw_low in seg_low:
                    matched = True
            else:
                if kw_strip in seg_text:
                    matched = True

            if matched:
                matched_keywords.append(kw_strip)
                if is_specific:
                    matched_specific += 1
                else:
                    matched_generic += 1

        if matched_specific + matched_generic == 0:
            continue

        # scoring: specific matches are strong; if no specific keywords in entry, generic matches can be strong
        if total_specific == 0:
            # generic-only entry: any match should be reasonably strong
            score = 0.6 + 0.4 * (matched_generic / max(1, total_generic))
        else:
            if matched_specific > 0:
                score = 0.5 + 0.4 * (matched_specific / max(1, total_specific)) + 0.1 * (matched_generic / max(1, total_generic))
            else:
                score = 0.2 * (matched_generic / max(1, total_generic))

        if station and station in entry['station_scope']:
            score = min(1.0, score + 0.05)

        if score > best_score:
            best_score = score
            best = entry
            best_matches = matched_keywords

    return best, best_score, best_matches

threshold = 0.55

records_out = []

for _, row in logs.iterrows():
    record_id = row['record_id']
    product_id = row['product_id']
    station = row['station']
    engineer_id = row['engineer_id'] if pd.notna(row['engineer_id']) else ''
    raw_reason_text = row['raw_reason_text'] if pd.notna(row['raw_reason_text']) else ''

    segments = split_segments(raw_reason_text)
    normalized = []
    seg_idx = 1
    for seg in segments:
        best, score, matches = match_segment(product_id, station, seg)
        if best and score >= threshold:
            conf = min(0.95, 0.55 + 0.4 * score)
            pred_code = best['code']
            pred_label = best['label']
            rationale = f"Matched keywords: {', '.join(matches[:6])}; score={score:.2f}."
        else:
            conf = 0.1 + 0.3 * score
            pred_code = 'UNKNOWN'
            pred_label = ''
            rationale = f"Low match score={score:.2f}; insufficient keyword alignment."
        normalized.append({
            'segment_id': f"{record_id}-S{seg_idx}",
            'span_text': seg,
            'pred_code': pred_code,
            'pred_label': pred_label,
            'confidence': round(conf, 3),
            'rationale': rationale
        })
        seg_idx += 1

    records_out.append({
        'record_id': record_id,
        'product_id': product_id,
        'station': station,
        'engineer_id': engineer_id,
        'raw_reason_text': raw_reason_text,
        'normalized': normalized
    })

out = {'records': records_out}

with open('/app/output/solution.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)

print('written', len(records_out))
